    "groups": [
      "Part number and description identify the component and its specifications.",
      "Quantity and unit price support purchasing and cost comparisons.",
      "Supplier complements the part number as a sourcing reference."
    ],
    "keep_intact": [
      "Part numbers and supplier names, especially long unbreakable identifiers.",
      "Quantities and unit-price values, so they remain easy to compare."
    ],
    "may_wrap": [
      "Descriptions can wrap at spaces; shorter cells in the same row can occupy the resulting height.",
      "The Unit price header can wrap if the price values remain readable."
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [186, 241, 47, 91, 154],
      "idea": "Protect every column's longest unbreakable value and the one-line price width, giving the remaining space to naturally wrapping descriptions."
    },
    {
      "name": "B",
      "widths": [186, 275, 47, 80, 131],
      "idea": "Give descriptions more room while preserving part numbers, accepting a wrapped price header and possible breaks or overflow in long supplier names."
